<?php

namespace App\Filament\Resources\SeoTechnicalAudits;

use App\Filament\Resources\SeoTechnicalAudits\Pages\ManageSeoTechnicalAudits;
use App\Filament\Resources\SeoTechnicalAudits\Tables\SeoTechnicalAuditsTable;
use App\Models\SeoTechnicalAudit;
use BackedEnum;
use Filament\Resources\Resource;
use Filament\Schemas\Schema;
use Filament\Support\Icons\Heroicon;
use Filament\Tables\Table;

/**
 * Fully system-generated by App\Domain\Seo\TechnicalSeoAuditor - there is
 * no create/edit form here on purpose, only a "اجرای بررسی جدید" header
 * action and a read-only issues view, mirroring SeoOpportunityResource.
 */
class SeoTechnicalAuditResource extends Resource
{
    protected static ?string $model = SeoTechnicalAudit::class;

    protected static string|BackedEnum|null $navigationIcon = Heroicon::OutlinedMagnifyingGlassCircle;

    protected static string|\UnitEnum|null $navigationGroup = 'مرکز سئو';

    protected static ?string $navigationLabel = 'ممیزی فنی سئو';

    protected static ?string $modelLabel = 'ممیزی فنی سئو';

    protected static ?string $pluralModelLabel = 'ممیزی‌های فنی سئو';

    public static function form(Schema $schema): Schema
    {
        return $schema->components([]);
    }

    public static function table(Table $table): Table
    {
        return SeoTechnicalAuditsTable::configure($table);
    }

    public static function getPages(): array
    {
        return [
            'index' => ManageSeoTechnicalAudits::route('/'),
        ];
    }
}
